values
  ('14f8bfaf-bcaf-42ad-a960-1f6e63955d11', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Painting as Studio Practice: Observation, Material, and Meaning', 'This opening topic establishes painting as a disciplined studio practice that joins looking, making, material control, and interpretation.', 0),
  ('e8385f7d-b3c4-43e9-a4f4-6e202d7beaf6', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '14f8bfaf-bcaf-42ad-a960-1f6e63955d11', 'subtopic'::public.curated_course_node_type, 'Studio habits and process documentation', 'Students begin building repeatable studio routines so progress can be observed, questioned, and improved rather than left to chance.', 0),
  ('407e4ccf-f685-4c23-a1fe-790de59ca5b8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e8385f7d-b3c4-43e9-a4f4-6e202d7beaf6', 'concept'::public.curated_course_node_type, 'Sketchbook logs, thumbnails, process photos', null, 0),
  ('15550c9e-e46c-42a2-90a8-4b94753267b8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e8385f7d-b3c4-43e9-a4f4-6e202d7beaf6', 'concept'::public.curated_course_node_type, 'Material tests and annotated experiments', null, 1),
  ('1a9fe209-85d9-4140-a750-f475586fab96', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e8385f7d-b3c4-43e9-a4f4-6e202d7beaf6', 'concept'::public.curated_course_node_type, 'Planning, revision, and reflective notes', null, 2),
  ('f057aa18-abc5-45c9-93ad-cb9302f5e4b8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '14f8bfaf-bcaf-42ad-a960-1f6e63955d11', 'subtopic'::public.curated_course_node_type, 'Observation as a painting method', 'Careful looking trains students to distinguish what they assume from what they actually see.', 1),
  ('b0b3e20c-4658-4002-9d5d-564ffc58025c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'f057aa18-abc5-45c9-93ad-cb9302f5e4b8', 'concept'::public.curated_course_node_type, 'Comparative measurement', null, 0),
  ('61658939-2fe0-446c-b316-73941773b545', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'f057aa18-abc5-45c9-93ad-cb9302f5e4b8', 'concept'::public.curated_course_node_type, 'Shape, edge, value, color temperature', null, 1),
  ('7b5b38d8-974f-45f1-b280-2b4935936f1d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'f057aa18-abc5-45c9-93ad-cb9302f5e4b8', 'concept'::public.curated_course_node_type, 'Slow looking and perceptual correction', null, 2),
  ('8b0900db-1ef2-4ccb-8d48-1cda5ea2809c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '14f8bfaf-bcaf-42ad-a960-1f6e63955d11', 'subtopic'::public.curated_course_node_type, 'Painting as visual argument', 'Even a beginning painting makes claims through emphasis, omission, composition, and handling.', 2),
  ('da794150-0ccf-46c3-9a38-9ead59c14045', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8b0900db-1ef2-4ccb-8d48-1cda5ea2809c', 'concept'::public.curated_course_node_type, 'Subject choice', null, 0),
  ('3a344e9d-a217-4117-9889-4d9ec66db62d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8b0900db-1ef2-4ccb-8d48-1cda5ea2809c', 'concept'::public.curated_course_node_type, 'Point of view', null, 1),
  ('3d7dd6f1-adcf-414c-9ca7-8a039bcb95dd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8b0900db-1ef2-4ccb-8d48-1cda5ea2809c', 'concept'::public.curated_course_node_type, 'Material rhetoric and expressive intent', null, 2),
  ('618e16b6-33be-42c6-9350-ae17acf8030f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Studio Safety, Materials, Supports, Grounds, and Tools', 'A strong painter understands the physical behavior and risks of tools, pigments, solvents, surfaces, and studio procedures. This section gives students practical control over the painting environment before technique becomes complex.', 1),
  ('68eda97b-4ccf-465c-82eb-2793c403f2d3', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '618e16b6-33be-42c6-9350-ae17acf8030f', 'subtopic'::public.curated_course_node_type, 'Safe studio practice', 'Safety knowledge protects the student, classmates, shared facilities, and finished work.', 0),
  ('deb2f10c-b06b-4930-8ba9-2fb3cf28f105', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '68eda97b-4ccf-465c-82eb-2793c403f2d3', 'concept'::public.curated_course_node_type, 'Ventilation and solvent handling', null, 0),
  ('7181bef6-e7ee-4f85-8756-3f8bdb60a9aa', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '68eda97b-4ccf-465c-82eb-2793c403f2d3', 'concept'::public.curated_course_node_type, 'Pigment toxicity and labeling', null, 1),
  ('abb3d4d8-ec67-456b-81d1-04b470d42bab', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '68eda97b-4ccf-465c-82eb-2793c403f2d3', 'concept'::public.curated_course_node_type, 'Cleanup, disposal, and shared-space protocols', null, 2),
  ('c8569679-096e-4fcb-ad21-80b02c2c833b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '618e16b6-33be-42c6-9350-ae17acf8030f', 'subtopic'::public.curated_course_node_type, 'Supports and grounds', 'Supports and grounds determine absorbency, tooth, durability, and how paint sits on the surface.', 1),
  ('9bef834f-87c0-48cc-843d-98a202c9281c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c8569679-096e-4fcb-ad21-80b02c2c833b', 'concept'::public.curated_course_node_type, 'Canvas, panel, paper, and found supports', null, 0),
  ('968e65a7-14c6-4eb4-8962-3c78a73b2c6f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c8569679-096e-4fcb-ad21-80b02c2c833b', 'concept'::public.curated_course_node_type, 'Gesso and grounds', null, 1),
  ('11c2c184-f1f4-433c-8c2b-812886ddcafd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c8569679-096e-4fcb-ad21-80b02c2c833b', 'concept'::public.curated_course_node_type, 'Texture, absorbency, and archival preparation', null, 2),
  ('e2efaac6-08cc-42e9-b3b8-30ec4d7e8481', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '618e16b6-33be-42c6-9350-ae17acf8030f', 'subtopic'::public.curated_course_node_type, 'Tools and studio setup', 'Tool choice changes the mark and the thinking process behind the mark.', 2),
  ('c82cd0ae-8d28-43ce-9682-976d58d9e235', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e2efaac6-08cc-42e9-b3b8-30ec4d7e8481', 'concept'::public.curated_course_node_type, 'Brush types and care', null, 0),
  ('caee5b2b-ee16-4116-8235-7071ce8f3261', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e2efaac6-08cc-42e9-b3b8-30ec4d7e8481', 'concept'::public.curated_course_node_type, 'Palette knives, rags, rollers, and improvised tools', null, 1),
  ('7347638a-cd97-422d-84a1-f50dd5682bcf', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e2efaac6-08cc-42e9-b3b8-30ec4d7e8481', 'concept'::public.curated_course_node_type, 'Palette organization and lighting', null, 2),
  ('5c093ed2-1cfb-454e-a1ac-67e98819278f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Color Theory for Painters', 'Color is both technical and perceptual: it involves pigment behavior, light, relationships, emotion, and cultural meaning. Students learn to mix intentionally and to make color decisions that serve the painting.', 2),
  ('90b44e30-5cbb-4cff-8065-84edc2c012cd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5c093ed2-1cfb-454e-a1ac-67e98819278f', 'subtopic'::public.curated_course_node_type, 'Color mixing in paint', 'Mixing teaches students the difference between theoretical color wheels and the real behavior of pigments.', 0),
  ('641ea107-005e-4f2d-83d2-c2fbba56e982', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '90b44e30-5cbb-4cff-8065-84edc2c012cd', 'concept'::public.curated_course_node_type, 'Hue, value, chroma', null, 0),
  ('af0d7ab0-041a-4458-8b98-9c539b2bbbc6', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '90b44e30-5cbb-4cff-8065-84edc2c012cd', 'concept'::public.curated_course_node_type, 'Limited palettes', null, 1),
  ('c2e1133a-6378-4656-b468-dd278a98d7de', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '90b44e30-5cbb-4cff-8065-84edc2c012cd', 'concept'::public.curated_course_node_type, 'Tints, shades, tones, complements', null, 2),
  ('10c9c9ba-82a6-48d1-8858-a1b6bff9283b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5c093ed2-1cfb-454e-a1ac-67e98819278f', 'subtopic'::public.curated_course_node_type, 'Color relationships and perception', 'A color changes depending on what surrounds it, so painters must judge relationships rather than isolated swatches.', 1),
  ('1a852ba2-7d2c-4449-91d9-0882e27ea91c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '10c9c9ba-82a6-48d1-8858-a1b6bff9283b', 'concept'::public.curated_course_node_type, 'Simultaneous contrast', null, 0),
  ('7b771896-22f8-417f-bde9-676c7bf0fb8c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '10c9c9ba-82a6-48d1-8858-a1b6bff9283b', 'concept'::public.curated_course_node_type, 'Warm/cool shifts', null, 1),
  ('d57639c7-856e-430a-bfad-02efea919ee8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '10c9c9ba-82a6-48d1-8858-a1b6bff9283b', 'concept'::public.curated_course_node_type, 'Optical vibration and afterimage', null, 2),
  ('69ec9877-6f38-436e-8998-42a7fa282dc0', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5c093ed2-1cfb-454e-a1ac-67e98819278f', 'subtopic'::public.curated_course_node_type, 'Expressive and symbolic color', 'Color carries mood, memory, identity, and cultural associations that can deepen content.', 2),
  ('73b2b292-cce1-49d9-9ea4-83079f709b00', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '69ec9877-6f38-436e-8998-42a7fa282dc0', 'concept'::public.curated_course_node_type, 'Local vs invented color', null, 0),
  ('a53ca1a7-b0e7-49ec-b695-becfcfb380ab', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '69ec9877-6f38-436e-8998-42a7fa282dc0', 'concept'::public.curated_course_node_type, 'Palette as mood structure', null, 1),
  ('a6fe8c18-7152-43c4-9721-424ec2baa06f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '69ec9877-6f38-436e-8998-42a7fa282dc0', 'concept'::public.curated_course_node_type, 'Historical and contemporary color strategies', null, 2),
  ('12aed93d-f085-4a97-a92a-83be0d5d3478', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Value, Light, Shadow, and Tonal Structure', 'Value gives paintings legibility, form, weight, atmosphere, and drama. Students learn to build images that remain coherent even before color is added.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c2e4f9ec-586d-4d61-a94a-97530b05cf35', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '12aed93d-f085-4a97-a92a-83be0d5d3478', 'subtopic'::public.curated_course_node_type, 'Value scales and tonal grouping', 'Value control helps students organize complex scenes into readable structures.', 0),
