  ('958406b7-d75e-4381-968d-2bb65a637648', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c2e4f9ec-586d-4d61-a94a-97530b05cf35', 'concept'::public.curated_course_node_type, 'Value compression and expansion', null, 2),
  ('2d614193-6b45-4674-9c27-39509dc2c2de', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '12aed93d-f085-4a97-a92a-83be0d5d3478', 'subtopic'::public.curated_course_node_type, 'Light logic', 'Understanding light lets students paint form with credibility instead of copying isolated patches.', 1),
