  ('105e8551-36ba-42bb-afad-335c3146be78', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '2d614193-6b45-4674-9c27-39509dc2c2de', 'concept'::public.curated_course_node_type, 'Specular and diffuse reflection', null, 2),
  ('9cd6418a-84b7-4b78-8ff1-e8ced1b0fb4a', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '12aed93d-f085-4a97-a92a-83be0d5d3478', 'subtopic'::public.curated_course_node_type, 'Atmosphere and depth', 'Tonal structure can create space, distance, and mood.', 2),
  ('4e00ff9f-713b-4f98-950e-efa8e9575894', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '9cd6418a-84b7-4b78-8ff1-e8ced1b0fb4a', 'concept'::public.curated_course_node_type, 'Aerial perspective', null, 0),
  ('2f7cc559-50ee-4429-bf99-d9b1ac250e77', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '9cd6418a-84b7-4b78-8ff1-e8ced1b0fb4a', 'concept'::public.curated_course_node_type, 'Lost and found edges', null, 1),
  ('08114d0b-c214-44e2-b113-5c3bc7d1be24', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '9cd6418a-84b7-4b78-8ff1-e8ced1b0fb4a', 'concept'::public.curated_course_node_type, 'Silhouette and massing', null, 2),
  ('ca80b730-1542-4d38-8a9d-9c8602f81ad3', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Drawing-to-Painting Transfer and Underpainting', 'Many paintings begin with a drawing structure, but painting demands that drawing stay flexible. This section teaches students how to move from line and plan into layered painted form.', 4),
  ('538c207f-cf79-4c11-8157-e6aead3eef3d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ca80b730-1542-4d38-8a9d-9c8602f81ad3', 'subtopic'::public.curated_course_node_type, 'Thumbnailing and compositional studies', 'Small studies let students test structure quickly before committing to a full painting.', 0),
  ('05dd3c3c-ef3c-4a3a-bbfc-6da9f3f84bbd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '538c207f-cf79-4c11-8157-e6aead3eef3d', 'concept'::public.curated_course_node_type, 'Cropping and format tests', null, 0),
  ('4c53b4a6-44bc-43f9-9fb4-1fafcc58191d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '538c207f-cf79-4c11-8157-e6aead3eef3d', 'concept'::public.curated_course_node_type, 'Notan studies', null, 1),
  ('93eccea0-8a6b-4db3-8052-6dafe3ed9e58', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '538c207f-cf79-4c11-8157-e6aead3eef3d', 'concept'::public.curated_course_node_type, 'Gesture studies and value maps', null, 2),
  ('31a19711-e665-428c-b903-fce865ad758b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ca80b730-1542-4d38-8a9d-9c8602f81ad3', 'subtopic'::public.curated_course_node_type, 'Transfer methods', 'Transfer techniques help students scale or preserve a drawing while still leaving room for painterly revision.', 1),
  ('ad725319-18d7-4618-8c93-671b9570293b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '31a19711-e665-428c-b903-fce865ad758b', 'concept'::public.curated_course_node_type, 'Grid transfer', null, 0),
  ('b42f6d7d-fb08-479b-babd-6d5be1743260', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '31a19711-e665-428c-b903-fce865ad758b', 'concept'::public.curated_course_node_type, 'Projection and tracing ethics', null, 1),
  ('3b1cbcf1-50c1-4192-9fea-563426d1bb24', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '31a19711-e665-428c-b903-fce865ad758b', 'concept'::public.curated_course_node_type, 'Direct drawing with brush', null, 2),
  ('fea78373-9d94-49f9-ae1e-1120a2c82ff3', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ca80b730-1542-4d38-8a9d-9c8602f81ad3', 'subtopic'::public.curated_course_node_type, 'Underpainting and block-in', 'Underpainting establishes value, color temperature, or compositional scaffolding.', 2),
