  ('d00508b9-25d4-4616-abc4-fba82dd726db', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'fea78373-9d94-49f9-ae1e-1120a2c82ff3', 'concept'::public.curated_course_node_type, 'Imprimatura', null, 1),
  ('08fd535b-9bde-4d54-9729-c6e44f66f31e', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'fea78373-9d94-49f9-ae1e-1120a2c82ff3', 'concept'::public.curated_course_node_type, 'Wipe-out and mass block-in', null, 2),
  ('5033bf24-cbb3-4f83-9f7f-c70dcb8bda05', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Paint Handling: Acrylic, Oil, Water-Based, and Mixed Media', 'Paint handling is the craft bridge between intention and visible form. Students compare media so they can choose processes suited to time, surface, texture, and revision.', 5),
  ('3d065b9e-46f7-4934-af6a-51fb4c2f2d70', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5033bf24-cbb3-4f83-9f7f-c70dcb8bda05', 'subtopic'::public.curated_course_node_type, 'Acrylic methods', 'Acrylic teaches speed, layering, opacity control, and medium-based modification.', 0),
  ('87f4efb1-f842-4106-82e5-cd05834c41e5', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d065b9e-46f7-4934-af6a-51fb4c2f2d70', 'concept'::public.curated_course_node_type, 'Open vs fast-drying acrylics', null, 0),
  ('3b84db93-99b7-4a55-bc82-6efbe13786a8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d065b9e-46f7-4934-af6a-51fb4c2f2d70', 'concept'::public.curated_course_node_type, 'Glazing, scumbling, impasto', null, 1),
  ('dd397c50-8799-4d78-9f8e-bdf4f8d36538', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d065b9e-46f7-4934-af6a-51fb4c2f2d70', 'concept'::public.curated_course_node_type, 'Acrylic mediums and gels', null, 2),
  ('72b5689b-7480-4984-8a7e-84c4089c6e2b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5033bf24-cbb3-4f83-9f7f-c70dcb8bda05', 'subtopic'::public.curated_course_node_type, 'Oil and water-miscible oil methods', 'Oil introduces slower working time, blending, edge control, and layered luminosity.', 1),
  ('f7b0beb6-79a6-4845-bc88-b6fcee1be22d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '72b5689b-7480-4984-8a7e-84c4089c6e2b', 'concept'::public.curated_course_node_type, 'Fat-over-lean logic', null, 0),
  ('18115f09-4e72-4ded-850e-4ea6e1b50312', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '72b5689b-7480-4984-8a7e-84c4089c6e2b', 'concept'::public.curated_course_node_type, 'Mediums and solvent alternatives', null, 1),
  ('895df9c8-4f1c-4d22-a2ac-32c9731b6fb7', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '72b5689b-7480-4984-8a7e-84c4089c6e2b', 'concept'::public.curated_course_node_type, 'Wet-into-wet and indirect methods', null, 2),
  ('75580f9f-2f8a-4ac2-8754-7932c6a3c5cd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '5033bf24-cbb3-4f83-9f7f-c70dcb8bda05', 'subtopic'::public.curated_course_node_type, 'Watercolor, gouache, and mixed approaches', 'Water-based and hybrid media expand the painter''s vocabulary of transparency, flatness, stain, and surface.', 2),
  ('1ef681a0-e6db-4795-8e76-7d6036bfcd89', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '75580f9f-2f8a-4ac2-8754-7932c6a3c5cd', 'concept'::public.curated_course_node_type, 'Transparent washes', null, 0),
  ('880ba837-5260-4e95-a15b-d51b0af12da8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '75580f9f-2f8a-4ac2-8754-7932c6a3c5cd', 'concept'::public.curated_course_node_type, 'Opaque gouache layers', null, 1),
  ('7ac4e9e4-3a8e-442a-ab5c-9257b47899c9', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '75580f9f-2f8a-4ac2-8754-7932c6a3c5cd', 'concept'::public.curated_course_node_type, 'Collage, drawing media, and nontraditional marks', null, 2),
  ('cee2287c-373e-48a0-8935-e91fe2db18b4', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Composition, Format, Scale, and Pictorial Space', 'Composition is how a painting directs attention, movement, balance, and interpretation. Students learn to organize the rectangle or other format as an active visual field.', 6),
  ('8bc5d004-25f3-45be-ad41-21029a524930', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'cee2287c-373e-48a0-8935-e91fe2db18b4', 'subtopic'::public.curated_course_node_type, 'Design principles in painting', 'Design principles give students language for why a painting holds together or falls apart.', 0);
