values
  ('15bafa88-bd0e-44fa-b199-fb759a6306cf', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8bc5d004-25f3-45be-ad41-21029a524930', 'concept'::public.curated_course_node_type, 'Balance, rhythm, contrast, emphasis', null, 0),
