  ('13a15d80-468b-4cd9-b19d-5176b3d61a67', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8bc5d004-25f3-45be-ad41-21029a524930', 'concept'::public.curated_course_node_type, 'Negative space', null, 2),
  ('589883e9-4c3b-4d9f-9d46-39516d5fc515', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'cee2287c-373e-48a0-8935-e91fe2db18b4', 'subtopic'::public.curated_course_node_type, 'Format and scale', 'Changing size or proportion changes the viewer''s bodily relationship to the work.', 1),
  ('7e733637-34f9-4ed2-9916-609506e039ca', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '589883e9-4c3b-4d9f-9d46-39516d5fc515', 'concept'::public.curated_course_node_type, 'Horizontal, vertical, square, shaped formats', null, 0),
  ('4ed6d5bb-55a4-4263-bf03-899790783127', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '589883e9-4c3b-4d9f-9d46-39516d5fc515', 'concept'::public.curated_course_node_type, 'Small studies vs large paintings', null, 1),
  ('dee5122c-15cb-48d5-b910-e4006fccb9e0', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '589883e9-4c3b-4d9f-9d46-39516d5fc515', 'concept'::public.curated_course_node_type, 'Intimacy, distance, and physical reach', null, 2),
  ('16aada35-9fea-47d9-80b6-888f3a220efb', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'cee2287c-373e-48a0-8935-e91fe2db18b4', 'subtopic'::public.curated_course_node_type, 'Pictorial space', 'Space can be illusionistic, shallow, fractured, or symbolic depending on the painter''s aim.', 2),
  ('d3e1730c-eecd-4655-bb42-eb6b2dffd2c4', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '16aada35-9fea-47d9-80b6-888f3a220efb', 'concept'::public.curated_course_node_type, 'Linear perspective', null, 0),
  ('4ecd2f37-209f-480f-803e-4d471a134b57', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '16aada35-9fea-47d9-80b6-888f3a220efb', 'concept'::public.curated_course_node_type, 'Overlapping and spatial cues', null, 1),
  ('eb38cbdb-48df-4ba1-ba5b-b73dd26e73e4', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '16aada35-9fea-47d9-80b6-888f3a220efb', 'concept'::public.curated_course_node_type, 'Flattening, pattern, and ambiguity', null, 2),
  ('da043f6c-7dfc-45f8-baef-5965124d6157', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Still Life: Observation, Objects, and Surface', 'Still life gives students controlled conditions for studying form, material, light, composition, and symbolic meaning. It is the ideal first arena for disciplined painting from observation.', 7),
  ('204d10f9-ba4e-4e07-8847-13e189ea26e0', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'da043f6c-7dfc-45f8-baef-5965124d6157', 'subtopic'::public.curated_course_node_type, 'Object structure and proportion', 'Students learn to build believable forms through comparison and correction.', 0),
  ('339d7337-a236-419c-a930-335addb80471', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '204d10f9-ba4e-4e07-8847-13e189ea26e0', 'concept'::public.curated_course_node_type, 'Ellipses and boxes', null, 0),
  ('6183609f-0724-44eb-a066-62b448cd468b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '204d10f9-ba4e-4e07-8847-13e189ea26e0', 'concept'::public.curated_course_node_type, 'Measuring relationships', null, 1),
  ('8d164966-f7cb-48a1-b21c-810d4421fd91', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '204d10f9-ba4e-4e07-8847-13e189ea26e0', 'concept'::public.curated_course_node_type, 'Volume and construction', null, 2),
  ('6ffc2de9-0fef-410b-ab81-0971574813e4', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'da043f6c-7dfc-45f8-baef-5965124d6157', 'subtopic'::public.curated_course_node_type, 'Surface and material description', 'Painting surfaces trains the eye to separate color, value, texture, and reflection.', 1),
  ('7fa14401-92ae-451a-aedb-d81d29f5e2ab', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '6ffc2de9-0fef-410b-ab81-0971574813e4', 'concept'::public.curated_course_node_type, 'Glass, metal, fabric, fruit, ceramics', null, 0),
  ('490718e6-2ae1-4286-a924-545f516a063c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '6ffc2de9-0fef-410b-ab81-0971574813e4', 'concept'::public.curated_course_node_type, 'Edges and highlights', null, 1),
  ('45e896d9-8fe7-425a-8745-e9310b400099', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '6ffc2de9-0fef-410b-ab81-0971574813e4', 'concept'::public.curated_course_node_type, 'Texture vs pattern', null, 2),
  ('3d44213c-b760-4c57-be64-d9d85a438944', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'da043f6c-7dfc-45f8-baef-5965124d6157', 'subtopic'::public.curated_course_node_type, 'Meaning in objects', 'Still life can move beyond exercise into personal, cultural, or historical interpretation.', 2),
  ('0ac8a544-bd02-4d6e-bf80-87b0ce3cc6df', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d44213c-b760-4c57-be64-d9d85a438944', 'concept'::public.curated_course_node_type, 'Vanitas and symbolic traditions', null, 0),
  ('7b16dd4d-3d53-40ba-bab6-bf7fd29562d3', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d44213c-b760-4c57-be64-d9d85a438944', 'concept'::public.curated_course_node_type, 'Domestic objects and identity', null, 1),
  ('873f03d2-f814-42df-93ca-61670c5fd7e1', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '3d44213c-b760-4c57-be64-d9d85a438944', 'concept'::public.curated_course_node_type, 'Arrangement as narrative', null, 2),
  ('4fae1fc7-0b3a-4c96-9c73-f212a437148c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Landscape, Interior, and Environment', 'Landscape and interior painting extend observation into space, weather, atmosphere, architecture, and place. Students learn to simplify the visual world without losing its felt complexity.', 8),
  ('ef1e99d1-55c5-4691-a68e-bb8fe4d6de47', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4fae1fc7-0b3a-4c96-9c73-f212a437148c', 'subtopic'::public.curated_course_node_type, 'Landscape fundamentals', 'Landscape teaches large value masses, atmospheric depth, and changing light.', 0),
  ('0773b449-4b63-417a-89cf-bdae5d8682de', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ef1e99d1-55c5-4691-a68e-bb8fe4d6de47', 'concept'::public.curated_course_node_type, 'Sky, ground, horizon', null, 0),
  ('3f9fab0e-c93f-45bb-8ba0-f80b94493733', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ef1e99d1-55c5-4691-a68e-bb8fe4d6de47', 'concept'::public.curated_course_node_type, 'Aerial perspective', null, 1),
  ('12b5fcec-5003-4dad-b49e-bb1e954e5eb5', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ef1e99d1-55c5-4691-a68e-bb8fe4d6de47', 'concept'::public.curated_course_node_type, 'Plein air studies and photo references', null, 2),
  ('8aa0d197-c3ee-4e2f-b7b7-f2ccb48e4dba', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4fae1fc7-0b3a-4c96-9c73-f212a437148c', 'subtopic'::public.curated_course_node_type, 'Interior space', 'Interior painting connects perspective, light, objects, and human trace.', 1),
  ('4835e03b-ac7b-4f6c-9100-bc3783705d87', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8aa0d197-c3ee-4e2f-b7b7-f2ccb48e4dba', 'concept'::public.curated_course_node_type, 'One- and two-point perspective', null, 0),
  ('45cc70eb-32ba-4dbb-b0fa-fed9346e4bf7', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8aa0d197-c3ee-4e2f-b7b7-f2ccb48e4dba', 'concept'::public.curated_course_node_type, 'Windows and artificial light', null, 1),
  ('7ec94017-92dd-4db5-b074-1dcd8e76a688', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8aa0d197-c3ee-4e2f-b7b7-f2ccb48e4dba', 'concept'::public.curated_course_node_type, 'Rooms as psychological spaces', null, 2),
  ('11f56193-6787-4aef-9513-270b505690ff', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4fae1fc7-0b3a-4c96-9c73-f212a437148c', 'subtopic'::public.curated_course_node_type, 'Place, ecology, and memory', 'Environment can become content, not only scenery.', 2),
  ('6beaf9d2-cec5-49b1-b22b-d75e224dbb8f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '11f56193-6787-4aef-9513-270b505690ff', 'concept'::public.curated_course_node_type, 'Urban and rural visual language', null, 0),
  ('50156448-3a1b-4843-b3eb-61cc91f19214', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '11f56193-6787-4aef-9513-270b505690ff', 'concept'::public.curated_course_node_type, 'Climate and season', null, 1),
  ('2f55eddc-31c5-4bcb-86ef-0f27363c1578', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '11f56193-6787-4aef-9513-270b505690ff', 'concept'::public.curated_course_node_type, 'Personal geography and cultural landscape', null, 2),
  ('671ee085-7bd0-415e-875d-7d69581a199a', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Figure, Portrait, Body, and Identity', 'A first figure-painting unit introduces the body as form, presence, gesture, and social subject. The aim is not mastery of anatomy, but a responsible and observant foundation.', 9),
  ('e5ac6efe-6ad1-490a-b2c4-f37e52275492', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '671ee085-7bd0-415e-875d-7d69581a199a', 'subtopic'::public.curated_course_node_type, 'Figure proportion and gesture', 'Gesture helps students see the body as movement and weight before details take over.', 0),
  ('be6a5983-a6c7-4409-bc0a-ed4b7e5ea251', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e5ac6efe-6ad1-490a-b2c4-f37e52275492', 'concept'::public.curated_course_node_type, 'Line of action', null, 0);
