  ('8d38dc48-0fb0-4288-bca2-b2c4c7be0f4a', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '7414fc04-6445-4364-b18a-c8d4fc6d8008', 'concept'::public.curated_course_node_type, 'Avoiding stereotype', null, 1),
