  ('8e145cc8-44de-4b5b-a8d3-06154fddd70d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Abstraction, Gesture, Process, and Experiment', 'Abstraction teaches students that painting can be driven by color, movement, material behavior, systems, and discovery rather than direct depiction. Experiment becomes a method rather than a detour.', 10),
  ('e0e4a13e-e152-4fb9-898b-ef5e75b9473f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8e145cc8-44de-4b5b-a8d3-06154fddd70d', 'subtopic'::public.curated_course_node_type, 'Gesture and mark-making', 'Marks reveal speed, pressure, touch, and decision-making.', 0),
  ('20f6ea97-dd68-4902-a746-857e6024e364', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e0e4a13e-e152-4fb9-898b-ef5e75b9473f', 'concept'::public.curated_course_node_type, 'Brush gesture', null, 0),
  ('4b9ce490-5436-4edd-9293-3c3ddba1c333', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e0e4a13e-e152-4fb9-898b-ef5e75b9473f', 'concept'::public.curated_course_node_type, 'Scraping, pouring, wiping', null, 1),
  ('2b007b28-2d78-4c1d-9a7f-ecff86868f22', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'e0e4a13e-e152-4fb9-898b-ef5e75b9473f', 'concept'::public.curated_course_node_type, 'Rhythmic and calligraphic marks', null, 2),
  ('ea58c632-711f-463b-a898-de8f99e29589', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8e145cc8-44de-4b5b-a8d3-06154fddd70d', 'subtopic'::public.curated_course_node_type, 'Process-based painting', 'Process-based work gives rules, chance, repetition, or material reactions a visible role.', 1),
  ('4de68ed8-64be-4bf7-9fc4-0e1219fd7490', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ea58c632-711f-463b-a898-de8f99e29589', 'concept'::public.curated_course_node_type, 'Layer accumulation', null, 0),
  ('63a1d1d9-43fb-43a8-b7e5-eb7d61231a0b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ea58c632-711f-463b-a898-de8f99e29589', 'concept'::public.curated_course_node_type, 'Masking and removal', null, 1),
  ('1af4d07e-a2d4-4ce1-a490-e57e89cd8727', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'ea58c632-711f-463b-a898-de8f99e29589', 'concept'::public.curated_course_node_type, 'Chance operations and constraints', null, 2),
  ('4feb00de-bc43-40b7-a0de-3e44b33fbb5c', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '8e145cc8-44de-4b5b-a8d3-06154fddd70d', 'subtopic'::public.curated_course_node_type, 'Abstraction and figuration as a spectrum', 'Students learn that images can move between recognition and ambiguity.', 2),
  ('ec230a51-2e4d-4bf1-a389-ef8eb35d68dc', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4feb00de-bc43-40b7-a0de-3e44b33fbb5c', 'concept'::public.curated_course_node_type, 'Hybrid image languages', null, 0),
  ('053f103b-b773-42c0-9d21-de7077a9c5bc', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4feb00de-bc43-40b7-a0de-3e44b33fbb5c', 'concept'::public.curated_course_node_type, 'Fragmentation and simplification', null, 1),
  ('f9e233bc-5428-4d9e-a1be-12ded7bdbf8a', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '4feb00de-bc43-40b7-a0de-3e44b33fbb5c', 'concept'::public.curated_course_node_type, 'Nonobjective composition', null, 2),
  ('404843e4-e654-444c-8921-252a44d0e90d', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Narrative, Symbol, Image, and Concept', 'Painting can tell stories, imply events, construct symbols, or stage questions. This topic helps students connect technique to content without reducing painting to illustration.', 11),
  ('c702803a-6200-491b-a4ef-95d34b524af1', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '404843e4-e654-444c-8921-252a44d0e90d', 'subtopic'::public.curated_course_node_type, 'Narrative strategies', 'Narrative painting uses sequence, setting, gesture, and omission to invite interpretation.', 0),
  ('19e13d93-73ca-4734-bc72-41dcb362b4ad', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c702803a-6200-491b-a4ef-95d34b524af1', 'concept'::public.curated_course_node_type, 'Single-scene narrative', null, 0),
  ('ed29b30b-6294-411e-90e3-476aab69d35b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c702803a-6200-491b-a4ef-95d34b524af1', 'concept'::public.curated_course_node_type, 'Before/after implication', null, 1),
  ('196e279d-50c6-4ddd-83d6-8992205e2ec3', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'c702803a-6200-491b-a4ef-95d34b524af1', 'concept'::public.curated_course_node_type, 'Ambiguity and open endings', null, 2),
  ('48645ae3-3ebd-4b92-8c73-2a2818bf1f3b', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '404843e4-e654-444c-8921-252a44d0e90d', 'subtopic'::public.curated_course_node_type, 'Symbol and metaphor', 'Symbols make content more layered when they are handled thoughtfully.', 1),
  ('41fb2084-9b84-4651-b320-69d88f0f2053', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '48645ae3-3ebd-4b92-8c73-2a2818bf1f3b', 'concept'::public.curated_course_node_type, 'Personal iconography', null, 0),
  ('b9fceffa-ab44-4db7-8640-7d0f4f39152f', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '48645ae3-3ebd-4b92-8c73-2a2818bf1f3b', 'concept'::public.curated_course_node_type, 'Cultural symbols', null, 1),
  ('59949d3e-9c85-476f-932d-989f6a2a1641', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '48645ae3-3ebd-4b92-8c73-2a2818bf1f3b', 'concept'::public.curated_course_node_type, 'Metaphor through object, color, and scale', null, 2),
  ('fad4292b-83f9-46a0-a1b5-47ea09248117', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '404843e4-e654-444c-8921-252a44d0e90d', 'subtopic'::public.curated_course_node_type, 'Image sources and translation', 'Students learn to transform sources rather than merely copy them.', 2),
  ('acbf96d1-3ac4-4711-ab88-120847f250b0', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'fad4292b-83f9-46a0-a1b5-47ea09248117', 'concept'::public.curated_course_node_type, 'Photo reference ethics', null, 0),
  ('97d872a4-8839-44d8-95e0-9403fe63c8cd', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'fad4292b-83f9-46a0-a1b5-47ea09248117', 'concept'::public.curated_course_node_type, 'Appropriation and citation', null, 1),
  ('885246d9-404c-4ab8-9848-8b67da502088', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'fad4292b-83f9-46a0-a1b5-47ea09248117', 'concept'::public.curated_course_node_type, 'Collage, screens, and mediated images', null, 2),
  ('f86df4ef-c5c4-4075-86e9-db4c539cc9f5', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Historical and Contemporary Painting Contexts', 'Students paint better when they understand that each studio decision has precedents and consequences. This section connects assignments to historical movements, contemporary practices, and museum-quality looking.', 12),
  ('a3bf5202-42b7-4317-8c29-6bae42952095', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'f86df4ef-c5c4-4075-86e9-db4c539cc9f5', 'subtopic'::public.curated_course_node_type, 'Painting traditions and movements', 'Historical context gives students a vocabulary of approaches to borrow, resist, or revise.', 0),
  ('b6e2f6b2-3067-478f-be7c-d412d55bbc45', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'a3bf5202-42b7-4317-8c29-6bae42952095', 'concept'::public.curated_course_node_type, 'Still life, landscape, portrait traditions', null, 0),
  ('f1f44b34-6b43-403f-aa22-7173a35b3d53', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'a3bf5202-42b7-4317-8c29-6bae42952095', 'concept'::public.curated_course_node_type, 'Modernism and abstraction', null, 1);
