  ('bb9a3147-5dce-4a77-b321-08d39f3c2c74', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Critique, Visual Language, and Studio Dialogue', 'Critique turns private studio work into shared inquiry. Students learn to describe, analyze, interpret, and revise paintings through precise language and generous intellectual attention.', 13),
