  ('dea4bd29-fd10-48a2-81c5-2007060b2ae5', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '60a1c61a-60d0-4146-a580-96bd919a6834', 'concept'::public.curated_course_node_type, 'Silent looking', null, 0),
