  ('eaf1f73f-e09e-4d59-b695-c75d694b2e2e', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '60a1c61a-60d0-4146-a580-96bd919a6834', 'concept'::public.curated_course_node_type, 'Artist questions and peer response', null, 2),
