  ('4ebc73ce-ad07-4630-9c6c-53c0afd3eb04', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '77340f2c-1c36-48e8-bb3d-2f3164913cd2', 'concept'::public.curated_course_node_type, 'Material and process language', null, 2),
