  ('cb172b0f-3b63-465f-b240-04f7c97d2ae8', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'a7a4a690-8d33-48a8-a0bd-42fe7a22e6fa', 'concept'::public.curated_course_node_type, 'Actionable feedback', null, 0),
  ('9542a818-c17c-46a4-92e8-e7bd0b725fbc', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'a7a4a690-8d33-48a8-a0bd-42fe7a22e6fa', 'concept'::public.curated_course_node_type, 'Revision plans', null, 1),
  ('e16f0946-cadc-4cf5-8fb3-c72f3e70c9db', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', 'a7a4a690-8d33-48a8-a0bd-42fe7a22e6fa', 'concept'::public.curated_course_node_type, 'Reflective critique notes', null, 2),
