  ('29c00c3b-e27f-4f97-8456-48e2da1543a6', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', null, 'topic'::public.curated_course_node_type, 'Professional Practice, Ethics, Materials Sustainability, and Studio Habits', 'Even introductory students benefit from professional habits: ethical image use, sustainable material choices, accurate documentation, and respectful studio culture. These practices support long-term creative work.', 16),
  ('28eb45b8-dc75-46c3-89cb-76677afc2d7a', 'b8c9d0e1-2f3a-4b60-9e90-0f1a2b3c4d60', '29c00c3b-e27f-4f97-8456-48e2da1543a6', 'subtopic'::public.curated_course_node_type, 'Ethical image and source use', 'Painters must understand when source material becomes research, influence, quotation, or misuse.', 0),
