update public.learning_paths
set
  title = 'Painting I',
  goal = 'Painting I',
  summary = 'A first painting studio in which students handle basic painting media, mix color intentionally, and build critique and portfolio habits, with scaffolding for beginners.',
  data = $pa1json${"slug": "painting-i", "title": "Painting I", "description": "A first painting studio in which students handle basic painting media, mix color intentionally, and build critique and portfolio habits, with scaffolding for beginners.", "topics": [{"id": "14f8bfaf-bcaf-42ad-a960-1f6e63955d11", "type": "topic", "title": "Painting as Studio Practice: Observation, Material, and Meaning", "description": "This opening topic establishes painting as a disciplined studio practice that joins looking, making, material control, and interpretation.", "children": [{"id": "e8385f7d-b3c4-43e9-a4f4-6e202d7beaf6", "type": "subtopic", "title": "Studio habits and process documentation", "children": [{"id": "407e4ccf-f685-4c23-a1fe-790de59ca5b8", "type": "concept", "title": "Sketchbook logs, thumbnails, process photos"}, {"id": "15550c9e-e46c-42a2-90a8-4b94753267b8", "type": "concept", "title": "Material tests and annotated experiments"}, {"id": "1a9fe209-85d9-4140-a750-f475586fab96", "type": "concept", "title": "Planning, revision, and reflective notes"}], "description": "Students begin building repeatable studio routines so progress can be observed, questioned, and improved rather than left to chance."}, {"id": "f057aa18-abc5-45c9-93ad-cb9302f5e4b8", "type": "subtopic", "title": "Observation as a painting method", "children": [{"id": "b0b3e20c-4658-4002-9d5d-564ffc58025c", "type": "concept", "title": "Comparative measurement"}, {"id": "61658939-2fe0-446c-b316-73941773b545", "type": "concept", "title": "Shape, edge, value, color temperature"}, {"id": "7b5b38d8-974f-45f1-b280-2b4935936f1d", "type": "concept", "title": "Slow looking and perceptual correction"}], "description": "Careful looking trains students to distinguish what they assume from what they actually see."}, {"id": "8b0900db-1ef2-4ccb-8d48-1cda5ea2809c", "type": "subtopic", "title": "Painting as visual argument", "children": [{"id": "da794150-0ccf-46c3-9a38-9ead59c14045", "type": "concept", "title": "Subject choice"}, {"id": "3a344e9d-a217-4117-9889-4d9ec66db62d", "type": "concept", "title": "Point of view"}, {"id": "3d7dd6f1-adcf-414c-9ca7-8a039bcb95dd", "type": "concept", "title": "Material rhetoric and expressive intent"}], "description": "Even a beginning painting makes claims through emphasis, omission, composition, and handling."}]}, {"id": "618e16b6-33be-42c6-9350-ae17acf8030f", "type": "topic", "title": "Studio Safety, Materials, Supports, Grounds, and Tools", "description": "A strong painter understands the physical behavior and risks of tools, pigments, solvents, surfaces, and studio procedures. This section gives students practical control over the painting environment before technique becomes complex.", "children": [{"id": "68eda97b-4ccf-465c-82eb-2793c403f2d3", "type": "subtopic", "title": "Safe studio practice", "children": [{"id": "deb2f10c-b06b-4930-8ba9-2fb3cf28f105", "type": "concept", "title": "Ventilation and solvent handling"}, {"id": "7181bef6-e7ee-4f85-8756-3f8bdb60a9aa", "type": "concept", "title": "Pigment toxicity and labeling"}, {"id": "abb3d4d8-ec67-456b-81d1-04b470d42bab", "type": "concept", "title": "Cleanup, disposal, and shared-space protocols"}], "description": "Safety knowledge protects the student, classmates, shared facilities, and finished work."}, {"id": "c8569679-096e-4fcb-ad21-80b02c2c833b", "type": "subtopic", "title": "Supports and grounds", "children": [{"id": "9bef834f-87c0-48cc-843d-98a202c9281c", "type": "concept", "title": "Canvas, panel, paper, and found supports"}, {"id": "968e65a7-14c6-4eb4-8962-3c78a73b2c6f", "type": "concept", "title": "Gesso and grounds"}, {"id": "11c2c184-f1f4-433c-8c2b-812886ddcafd", "type": "concept", "title": "Texture, absorbency, and archival preparation"}], "description": "Supports and grounds determine absorbency, tooth, durability, and how paint sits on the surface."}, {"id": "e2efaac6-08cc-42e9-b3b8-30ec4d7e8481", "type": "subtopic", "title": "Tools and studio setup", "children": [{"id": "c82cd0ae-8d28-43ce-9682-976d58d9e235", "type": "concept", "title": "Brush types and care"}, {"id": "caee5b2b-ee16-4116-8235-7071ce8f3261", "type": "concept", "title": "Palette knives, rags, rollers, and improvised tools"}, {"id": "7347638a-cd97-422d-84a1-f50dd5682bcf", "type": "concept", "title": "Palette organization and lighting"}], "description": "Tool choice changes the mark and the thinking process behind the mark."}]}, {"id": "5c093ed2-1cfb-454e-a1ac-67e98819278f", "type": "topic", "title": "Color Theory for Painters", "description": "Color is both technical and perceptual: it involves pigment behavior, light, relationships, emotion, and cultural meaning. Students learn to mix intentionally and to make color decisions that serve the painting.", "children": [{"id": "90b44e30-5cbb-4cff-8065-84edc2c012cd", "type": "subtopic", "title": "Color mixing in paint", "children": [{"id": "641ea107-005e-4f2d-83d2-c2fbba56e982", "type": "concept", "title": "Hue, value, chroma"}, {"id": "af0d7ab0-041a-4458-8b98-9c539b2bbbc6", "type": "concept", "title": "Limited palettes"}, {"id": "c2e1133a-6378-4656-b468-dd278a98d7de", "type": "concept", "title": "Tints, shades, tones, complements"}], "description": "Mixing teaches students the difference between theoretical color wheels and the real behavior of pigments."}, {"id": "10c9c9ba-82a6-48d1-8858-a1b6bff9283b", "type": "subtopic", "title": "Color relationships and perception", "children": [{"id": "1a852ba2-7d2c-4449-91d9-0882e27ea91c", "type": "concept", "title": "Simultaneous contrast"}, {"id": "7b771896-22f8-417f-bde9-676c7bf0fb8c", "type": "concept", "title": "Warm/cool shifts"}, {"id": "d57639c7-856e-430a-bfad-02efea919ee8", "type": "concept", "title": "Optical vibration and afterimage"}], "description": "A color changes depending on what surrounds it, so painters must judge relationships rather than isolated swatches."}, {"id": "69ec9877-6f38-436e-8998-42a7fa282dc0", "type": "subtopic", "title": "Expressive and symbolic color", "children": [{"id": "73b2b292-cce1-49d9-9ea4-83079f709b00", "type": "concept", "title": "Local vs invented color"}, {"id": "a53ca1a7-b0e7-49ec-b695-becfcfb380ab", "type": "concept", "title": "Palette as mood structure"}, {"id": "a6fe8c18-7152-43c4-9721-424ec2baa06f", "type": "concept", "title": "Historical and contemporary color strategies"}], "description": "Color carries mood, memory, identity, and cultural associations that can deepen content."}]}, {"id": "12aed93d-f085-4a97-a92a-83be0d5d3478", "type": "topic", "title": "Value, Light, Shadow, and Tonal Structure", "description": "Value gives paintings legibility, form, weight, atmosphere, and drama. Students learn to build images that remain coherent even before color is added.", "children": [{"id": "c2e4f9ec-586d-4d61-a94a-97530b05cf35", "type": "subtopic", "title": "Value scales and tonal grouping", "children": [{"id": "596f48b4-5301-437b-91a4-3a873597cf8c", "type": "concept", "title": "Nine-step and five-step scales"}, {"id": "704fe408-1440-4dcc-a4da-e3d030ca4dd8", "type": "concept", "title": "High-key and low-key schemes"}, {"id": "958406b7-d75e-4381-968d-2bb65a637648", "type": "concept", "title": "Value compression and expansion"}], "description": "Value control helps students organize complex scenes into readable structures."}, {"id": "2d614193-6b45-4674-9c27-39509dc2c2de", "type": "subtopic", "title": "Light logic", "children": [{"id": "d7795003-d224-41d7-9ecf-56d8d4352f78", "type": "concept", "title": "Light source direction"}, {"id": "90e931d2-3595-48dc-bbec-9cd6aa8afec7", "type": "concept", "title": "Core shadow, cast shadow, reflected light"}, {"id": "105e8551-36ba-42bb-afad-335c3146be78", "type": "concept", "title": "Specular and diffuse reflection"}], "description": "Understanding light lets students paint form with credibility instead of copying isolated patches."}, {"id": "9cd6418a-84b7-4b78-8ff1-e8ced1b0fb4a", "type": "subtopic", "title": "Atmosphere and depth", "children": [{"id": "4e00ff9f-713b-4f98-950e-efa8e9575894", "type": "concept", "title": "Aerial perspective"}, {"id": "2f7cc559-50ee-4429-bf99-d9b1ac250e77", "type": "concept", "title": "Lost and found edges"}, {"id": "08114d0b-c214-44e2-b113-5c3bc7d1be24", "type": "concept", "title": "Silhouette and massing"}], "description": "Tonal structure can create space, distance, and mood."}]}, {"id": "ca80b730-1542-4d38-8a9d-9c8602f81ad3", "type": "topic", "title": "Drawing-to-Painting Transfer and Underpainting", "description": "Many paintings begin with a drawing structure, but painting demands that drawing stay flexible. This section teaches students how to move from line and plan into layered painted form.", "children": [{"id": "538c207f-cf79-4c11-8157-e6aead3eef3d", "type": "subtopic", "title": "Thumbnailing and compositional studies", "children": [{"id": "05dd3c3c-ef3c-4a3a-bbfc-6da9f3f84bbd", "type": "concept", "title": "Cropping and format tests"}, {"id": "4c53b4a6-44bc-43f9-9fb4-1fafcc58191d", "type": "concept", "title": "Notan studies"}, {"id": "93eccea0-8a6b-4db3-8052-6dafe3ed9e58", "type": "concept", "title": "Gesture studies and value maps"}], "description": "Small studies let students test structure quickly before committing to a full painting."}, {"id": "31a19711-e665-428c-b903-fce865ad758b", "type": "subtopic", "title": "Transfer methods", "children": [{"id": "ad725319-18d7-4618-8c93-671b9570293b", "type": "concept", "title": "Grid transfer"}, {"id": "b42f6d7d-fb08-479b-babd-6d5be1743260", "type": "concept", "title": "Projection and tracing ethics"}, {"id": "3b1cbcf1-50c1-4192-9fea-563426d1bb24", "type": "concept", "title": "Direct drawing with brush"}], "description": "Transfer techniques help students scale or preserve a drawing while still leaving room for painterly revision."}, {"id": "fea78373-9d94-49f9-ae1e-1120a2c82ff3", "type": "subtopic", "title": "Underpainting and block-in", "children": [{"id": "8ed3dab8-d25e-49c0-99c4-a2fef60f7124", "type": "concept", "title": "Grisaille"}, {"id": "d00508b9-25d4-4616-abc4-fba82dd726db", "type": "concept", "title": "Imprimatura"}, {"id": "08fd535b-9bde-4d54-9729-c6e44f66f31e", "type": "concept", "title": "Wipe-out and mass block-in"}], "description": "Underpainting establishes value, color temperature, or compositional scaffolding."}]}, {"id": "5033bf24-cbb3-4f83-9f7f-c70dcb8bda05", "type": "topic", "title": "Paint Handling: Acrylic, Oil, Water-Based, and Mixed Media", "description": "Paint handling is the craft bridge between intention and visible form. Students compare media so they can choose processes suited to time, surface, texture, and revision.", "children": [{"id": "3d065b9e-46f7-4934-af6a-51fb4c2f2d70", "type": "subtopic", "title": "Acrylic methods", "children": [{"id": "87f4efb1-f842-4106-82e5-cd05834c41e5", "type": "concept", "title": "Open vs fast-drying acrylics"}, {"id": "3b84db93-99b7-4a55-bc82-6efbe13786a8", "type": "concept", "title": "Glazing, scumbling, impasto"}, {"id": "dd397c50-8799-4d78-9f8e-bdf4f8d36538", "type": "concept", "title": "Acrylic mediums and gels"}], "description": "Acrylic teaches speed, layering, opacity control, and medium-based modification."}, {"id": "72b5689b-7480-4984-8a7e-84c4089c6e2b", "type": "subtopic", "title": "Oil and water-miscible oil methods", "children": [{"id": "f7b0beb6-79a6-4845-bc88-b6fcee1be22d", "type": "concept", "title": "Fat-over-lean logic"}, {"id": "18115f09-4e72-4ded-850e-4ea6e1b50312", "type": "concept", "title": "Mediums and solvent alternatives"}, {"id": "895df9c8-4f1c-4d22-a2ac-32c9731b6fb7", "type": "concept", "title": "Wet-into-wet and indirect methods"}], "description": "Oil introduces slower working time, blending, edge control, and layered luminosity."}, {"id": "75580f9f-2f8a-4ac2-8754-7932c6a3c5cd", "type": "subtopic", "title": "Watercolor, gouache, and mixed approaches", "children": [{"id": "1ef681a0-e6db-4795-8e76-7d6036bfcd89", "type": "concept", "title": "Transparent washes"}, {"id": "880ba837-5260-4e95-a15b-d51b0af12da8", "type": "concept", "title": "Opaque gouache layers"}, {"id": "7ac4e9e4-3a8e-442a-ab5c-9257b47899c9", "type": "concept", "title": "Collage, drawing media, and nontraditional marks"}], "description": "Water-based and hybrid media expand the painter's vocabulary of transparency, flatness, stain, and surface."}]}, {"id": "cee2287c-373e-48a0-8935-e91fe2db18b4", "type": "topic", "title": "Composition, Format, Scale, and Pictorial Space", "description": "Composition is how a painting directs attention, movement, balance, and interpretation. Students learn to organize the rectangle or other format as an active visual field.", "children": [{"id": "8bc5d004-25f3-45be-ad41-21029a524930", "type": "subtopic", "title": "Design principles in painting", "children": [{"id": "15bafa88-bd0e-44fa-b199-fb759a6306cf", "type": "concept", "title": "Balance, rhythm, contrast, emphasis"}, {"id": "1b0c3fb8-6e75-4421-b758-6539acce2d84", "type": "concept", "title": "Unity and variety"}, {"id": "13a15d80-468b-4cd9-b19d-5176b3d61a67", "type": "concept", "title": "Negative space"}], "description": "Design principles give students language for why a painting holds together or falls apart."}, {"id": "589883e9-4c3b-4d9f-9d46-39516d5fc515", "type": "subtopic", "title": "Format and scale", "children": [{"id": "7e733637-34f9-4ed2-9916-609506e039ca", "type": "concept", "title": "Horizontal, vertical, square, shaped formats"}, {"id": "4ed6d5bb-55a4-4263-bf03-899790783127", "type": "concept", "title": "Small studies vs large paintings"}, {"id": "dee5122c-15cb-48d5-b910-e4006fccb9e0", "type": "concept", "title": "Intimacy, distance, and physical reach"}], "description": "Changing size or proportion changes the viewer's bodily relationship to the work."}, {"id": "16aada35-9fea-47d9-80b6-888f3a220efb", "type": "subtopic", "title": "Pictorial space", "children": [{"id": "d3e1730c-eecd-4655-bb42-eb6b2dffd2c4", "type": "concept", "title": "Linear perspective"}, {"id": "4ecd2f37-209f-480f-803e-4d471a134b57", "type": "concept", "title": "Overlapping and spatial cues"}, {"id": "eb38cbdb-48df-4ba1-ba5b-b73dd26e73e4", "type": "concept", "title": "Flattening, pattern, and ambiguity"}], "description": "Space can be illusionistic, shallow, fractured, or symbolic depending on the painter's aim."}]}, {"id": "da043f6c-7dfc-45f8-baef-5965124d6157", "type": "topic", "title": "Still Life: Observation, Objects, and Surface", "description": "Still life gives students controlled conditions for studying form, material, light, composition, and symbolic meaning. It is the ideal first arena for disciplined painting from observation.", "children": [{"id": "204d10f9-ba4e-4e07-8847-13e189ea26e0", "type": "subtopic", "title": "Object structure and proportion", "children": [{"id": "339d7337-a236-419c-a930-335addb80471", "type": "concept", "title": "Ellipses and boxes"}, {"id": "6183609f-0724-44eb-a066-62b448cd468b", "type": "concept", "title": "Measuring relationships"}, {"id": "8d164966-f7cb-48a1-b21c-810d4421fd91", "type": "concept", "title": "Volume and construction"}], "description": "Students learn to build believable forms through comparison and correction."}, {"id": "6ffc2de9-0fef-410b-ab81-0971574813e4", "type": "subtopic", "title": "Surface and material description", "children": [{"id": "7fa14401-92ae-451a-aedb-d81d29f5e2ab", "type": "concept", "title": "Glass, metal, fabric, fruit, ceramics"}, {"id": "490718e6-2ae1-4286-a924-545f516a063c", "type": "concept", "title": "Edges and highlights"}, {"id": "45e896d9-8fe7-425a-8745-e9310b400099", "type": "concept", "title": "Texture vs pattern"}], "description": "Painting surfaces trains the eye to separate color, value, texture, and reflection."}, {"id": "3d44213c-b760-4c57-be64-d9d85a438944", "type": "subtopic", "title": "Meaning in objects", "children": [{"id": "0ac8a544-bd02-4d6e-bf80-87b0ce3cc6df", "type": "concept", "title": "Vanitas and symbolic traditions"}, {"id": "7b16dd4d-3d53-40ba-bab6-bf7fd29562d3", "type": "concept", "title": "Domestic objects and identity"}, {"id": "873f03d2-f814-42df-93ca-61670c5fd7e1", "type": "concept", "title": "Arrangement as narrative"}], "description": "Still life can move beyond exercise into personal, cultural, or historical interpretation."}]}, {"id": "4fae1fc7-0b3a-4c96-9c73-f212a437148c", "type": "topic", "title": "Landscape, Interior, and Environment", "description": "Landscape and interior painting extend observation into space, weather, atmosphere, architecture, and place. Students learn to simplify the visual world without losing its felt complexity.", "children": [{"id": "ef1e99d1-55c5-4691-a68e-bb8fe4d6de47", "type": "subtopic", "title": "Landscape fundamentals", "children": [{"id": "0773b449-4b63-417a-89cf-bdae5d8682de", "type": "concept", "title": "Sky, ground, horizon"}, {"id": "3f9fab0e-c93f-45bb-8ba0-f80b94493733", "type": "concept", "title": "Aerial perspective"}, {"id": "12b5fcec-5003-4dad-b49e-bb1e954e5eb5", "type": "concept", "title": "Plein air studies and photo references"}], "description": "Landscape teaches large value masses, atmospheric depth, and changing light."}, {"id": "8aa0d197-c3ee-4e2f-b7b7-f2ccb48e4dba", "type": "subtopic", "title": "Interior space", "children": [{"id": "4835e03b-ac7b-4f6c-9100-bc3783705d87", "type": "concept", "title": "One- and two-point perspective"}, {"id": "45cc70eb-32ba-4dbb-b0fa-fed9346e4bf7", "type": "concept", "title": "Windows and artificial light"}, {"id": "7ec94017-92dd-4db5-b074-1dcd8e76a688", "type": "concept", "title": "Rooms as psychological spaces"}], "description": "Interior painting connects perspective, light, objects, and human trace."}, {"id": "11f56193-6787-4aef-9513-270b505690ff", "type": "subtopic", "title": "Place, ecology, and memory", "children": [{"id": "6beaf9d2-cec5-49b1-b22b-d75e224dbb8f", "type": "concept", "title": "Urban and rural visual language"}, {"id": "50156448-3a1b-4843-b3eb-61cc91f19214", "type": "concept", "title": "Climate and season"}, {"id": "2f55eddc-31c5-4bcb-86ef-0f27363c1578", "type": "concept", "title": "Personal geography and cultural landscape"}], "description": "Environment can become content, not only scenery."}]}, {"id": "671ee085-7bd0-415e-875d-7d69581a199a", "type": "topic", "title": "Figure, Portrait, Body, and Identity", "description": "A first figure-painting unit introduces the body as form, presence, gesture, and social subject. The aim is not mastery of anatomy, but a responsible and observant foundation.", "children": [{"id": "e5ac6efe-6ad1-490a-b2c4-f37e52275492", "type": "subtopic", "title": "Figure proportion and gesture", "children": [{"id": "be6a5983-a6c7-4409-bc0a-ed4b7e5ea251", "type": "concept", "title": "Line of action"}, {"id": "059c0fc7-1ca8-47e5-a03a-0e42651fdacd", "type": "concept", "title": "Mass and balance"}, {"id": "1f2d161c-3bca-4b39-9425-73c99f679103", "type": "concept", "title": "Simplified anatomy landmarks"}], "description": "Gesture helps students see the body as movement and weight before details take over."}, {"id": "2aac2373-e477-4370-ae40-075822006d25", "type": "subtopic", "title": "Portrait structure and likeness", "children": [{"id": "ca8a0dd2-a684-4b07-a086-2c166f6e4154", "type": "concept", "title": "Head planes"}, {"id": "79e0c610-4a7f-402a-b22f-11ed02255f19", "type": "concept", "title": "Feature placement"}, {"id": "845e2d6c-7b11-4da2-8c17-7f75c86e5b16", "type": "concept", "title": "Skin color as mixed relationships"}], "description": "Portrait painting trains students to observe subtle relationships and expressive cues."}, {"id": "7414fc04-6445-4364-b18a-c8d4fc6d8008", "type": "subtopic", "title": "Ethics of representing bodies", "children": [{"id": "7dd5d192-e782-4382-a7a4-6358745588cf", "type": "concept", "title": "Model etiquette"}, {"id": "8d38dc48-0fb0-4288-bca2-b2c4c7be0f4a", "type": "concept", "title": "Avoiding stereotype"}, {"id": "b5c2bb20-323b-4eac-a72c-02e9cfec26ff", "type": "concept", "title": "Self-portraiture and identity questions"}], "description": "Representation involves consent, power, identity, and context."}]}, {"id": "8e145cc8-44de-4b5b-a8d3-06154fddd70d", "type": "topic", "title": "Abstraction, Gesture, Process, and Experiment", "description": "Abstraction teaches students that painting can be driven by color, movement, material behavior, systems, and discovery rather than direct depiction. Experiment becomes a method rather than a detour.", "children": [{"id": "e0e4a13e-e152-4fb9-898b-ef5e75b9473f", "type": "subtopic", "title": "Gesture and mark-making", "children": [{"id": "20f6ea97-dd68-4902-a746-857e6024e364", "type": "concept", "title": "Brush gesture"}, {"id": "4b9ce490-5436-4edd-9293-3c3ddba1c333", "type": "concept", "title": "Scraping, pouring, wiping"}, {"id": "2b007b28-2d78-4c1d-9a7f-ecff86868f22", "type": "concept", "title": "Rhythmic and calligraphic marks"}], "description": "Marks reveal speed, pressure, touch, and decision-making."}, {"id": "ea58c632-711f-463b-a898-de8f99e29589", "type": "subtopic", "title": "Process-based painting", "children": [{"id": "4de68ed8-64be-4bf7-9fc4-0e1219fd7490", "type": "concept", "title": "Layer accumulation"}, {"id": "63a1d1d9-43fb-43a8-b7e5-eb7d61231a0b", "type": "concept", "title": "Masking and removal"}, {"id": "1af4d07e-a2d4-4ce1-a490-e57e89cd8727", "type": "concept", "title": "Chance operations and constraints"}], "description": "Process-based work gives rules, chance, repetition, or material reactions a visible role."}, {"id": "4feb00de-bc43-40b7-a0de-3e44b33fbb5c", "type": "subtopic", "title": "Abstraction and figuration as a spectrum", "children": [{"id": "ec230a51-2e4d-4bf1-a389-ef8eb35d68dc", "type": "concept", "title": "Hybrid image languages"}, {"id": "053f103b-b773-42c0-9d21-de7077a9c5bc", "type": "concept", "title": "Fragmentation and simplification"}, {"id": "f9e233bc-5428-4d9e-a1be-12ded7bdbf8a", "type": "concept", "title": "Nonobjective composition"}], "description": "Students learn that images can move between recognition and ambiguity."}]}, {"id": "404843e4-e654-444c-8921-252a44d0e90d", "type": "topic", "title": "Narrative, Symbol, Image, and Concept", "description": "Painting can tell stories, imply events, construct symbols, or stage questions. This topic helps students connect technique to content without reducing painting to illustration.", "children": [{"id": "c702803a-6200-491b-a4ef-95d34b524af1", "type": "subtopic", "title": "Narrative strategies", "children": [{"id": "19e13d93-73ca-4734-bc72-41dcb362b4ad", "type": "concept", "title": "Single-scene narrative"}, {"id": "ed29b30b-6294-411e-90e3-476aab69d35b", "type": "concept", "title": "Before/after implication"}, {"id": "196e279d-50c6-4ddd-83d6-8992205e2ec3", "type": "concept", "title": "Ambiguity and open endings"}], "description": "Narrative painting uses sequence, setting, gesture, and omission to invite interpretation."}, {"id": "48645ae3-3ebd-4b92-8c73-2a2818bf1f3b", "type": "subtopic", "title": "Symbol and metaphor", "children": [{"id": "41fb2084-9b84-4651-b320-69d88f0f2053", "type": "concept", "title": "Personal iconography"}, {"id": "b9fceffa-ab44-4db7-8640-7d0f4f39152f", "type": "concept", "title": "Cultural symbols"}, {"id": "59949d3e-9c85-476f-932d-989f6a2a1641", "type": "concept", "title": "Metaphor through object, color, and scale"}], "description": "Symbols make content more layered when they are handled thoughtfully."}, {"id": "fad4292b-83f9-46a0-a1b5-47ea09248117", "type": "subtopic", "title": "Image sources and translation", "children": [{"id": "acbf96d1-3ac4-4711-ab88-120847f250b0", "type": "concept", "title": "Photo reference ethics"}, {"id": "97d872a4-8839-44d8-95e0-9403fe63c8cd", "type": "concept", "title": "Appropriation and citation"}, {"id": "885246d9-404c-4ab8-9848-8b67da502088", "type": "concept", "title": "Collage, screens, and mediated images"}], "description": "Students learn to transform sources rather than merely copy them."}]}, {"id": "f86df4ef-c5c4-4075-86e9-db4c539cc9f5", "type": "topic", "title": "Historical and Contemporary Painting Contexts", "description": "Students paint better when they understand that each studio decision has precedents and consequences. This section connects assignments to historical movements, contemporary practices, and museum-quality looking.", "children": [{"id": "a3bf5202-42b7-4317-8c29-6bae42952095", "type": "subtopic", "title": "Painting traditions and movements", "children": [{"id": "b6e2f6b2-3067-478f-be7c-d412d55bbc45", "type": "concept", "title": "Still life, landscape, portrait traditions"}, {"id": "f1f44b34-6b43-403f-aa22-7173a35b3d53", "type": "concept", "title": "Modernism and abstraction"}, {"id": "ccb546db-ed62-4a70-ad4a-43ad57015c6e", "type": "concept", "title": "Expressionism, realism, and conceptual painting"}], "description": "Historical context gives students a vocabulary of approaches to borrow, resist, or revise."}, {"id": "f92eb3d4-1a39-453d-bbf1-b5ca7733b690", "type": "subtopic", "title": "Contemporary painting debates", "children": [{"id": "bff7771c-bf83-4f94-ae6b-877c942bc617", "type": "concept", "title": "Expanded painting and installation"}, {"id": "a92c289f-71f7-4937-b62d-7bba0839ee10", "type": "concept", "title": "Painting after photography and screens"}, {"id": "b7ffda2d-6eb4-4e0d-b518-5594028e1124", "type": "concept", "title": "Global and decolonial perspectives"}], "description": "Contemporary practice expands what painting can be and where it can live."}, {"id": "dbb41952-c58a-4bd4-9c4a-974c7e76fe7b", "type": "subtopic", "title": "Museum and artist research", "children": [{"id": "202ea808-0bd6-4cc4-884c-3a87b433799a", "type": "concept", "title": "Formal analysis"}, {"id": "243ea76f-c8da-4749-af97-66bc7a6fe0a2", "type": "concept", "title": "Artist interviews"}, {"id": "b1d76f03-c60a-41b1-b089-4a00b7e1dd21", "type": "concept", "title": "Exhibition and collection research"}], "description": "Research teaches students how to look beyond style into methods, questions, and contexts."}]}, {"id": "bb9a3147-5dce-4a77-b321-08d39f3c2c74", "type": "topic", "title": "Critique, Visual Language, and Studio Dialogue", "description": "Critique turns private studio work into shared inquiry. Students learn to describe, analyze, interpret, and revise paintings through precise language and generous intellectual attention.", "children": [{"id": "60a1c61a-60d0-4146-a580-96bd919a6834", "type": "subtopic", "title": "Critique formats", "children": [{"id": "dea4bd29-fd10-48a2-81c5-2007060b2ae5", "type": "concept", "title": "Silent looking"}, {"id": "7f77df11-881d-4820-a859-cfba6319d4c6", "type": "concept", "title": "Description before judgment"}, {"id": "eaf1f73f-e09e-4d59-b695-c75d694b2e2e", "type": "concept", "title": "Artist questions and peer response"}], "description": "Different formats support different kinds of learning and feedback."}, {"id": "77340f2c-1c36-48e8-bb3d-2f3164913cd2", "type": "subtopic", "title": "Visual vocabulary", "children": [{"id": "cc605d28-e2ad-40a4-95e9-133069f226da", "type": "concept", "title": "Value, chroma, edge, surface, scale"}, {"id": "2adecdc2-319b-46b6-bfb9-2ba2e39d9581", "type": "concept", "title": "Composition and spatial terms"}, {"id": "4ebc73ce-ad07-4630-9c6c-53c0afd3eb04", "type": "concept", "title": "Material and process language"}], "description": "Precise terms help students discuss paintings without vague preference language."}, {"id": "a7a4a690-8d33-48a8-a0bd-42fe7a22e6fa", "type": "subtopic", "title": "Feedback and revision", "children": [{"id": "cb172b0f-3b63-465f-b240-04f7c97d2ae8", "type": "concept", "title": "Actionable feedback"}, {"id": "9542a818-c17c-46a4-92e8-e7bd0b725fbc", "type": "concept", "title": "Revision plans"}, {"id": "e16f0946-cadc-4cf5-8fb3-c72f3e70c9db", "type": "concept", "title": "Reflective critique notes"}], "description": "Students learn to separate the value of the work from the value of a single draft."}]}, {"id": "875f8633-1999-4ec5-8827-54a40bae5f5f", "type": "topic", "title": "Iteration, Series Development, and Personal Voice", "description": "A strong painting practice develops through repeated attempts, variations, and questions. This topic introduces the idea that personal voice emerges through disciplined iteration rather than instant originality.", "children": [{"id": "16b1f842-7513-4e87-bd54-3f08add29cb3", "type": "subtopic", "title": "Studies and variations", "children": [{"id": "8696c849-e614-4ec3-8608-21ef010bff8e", "type": "concept", "title": "Color studies"}, {"id": "795b5f80-9dcf-455c-88be-b249fab55121", "type": "concept", "title": "Scale studies"}, {"id": "ce7bffa2-1699-4fad-8230-b16bf806b3c2", "type": "concept", "title": "Compositional variants"}], "description": "Studies allow students to test alternatives quickly and reduce fear of change."}, {"id": "9643a99b-a8fe-4433-a37e-a3e2d8fe84ec", "type": "subtopic", "title": "Series thinking", "children": [{"id": "e866e8be-a836-4580-ae9b-27e6be93d1c6", "type": "concept", "title": "Motif repetition"}, {"id": "85e57525-d6f4-4427-aace-58df83f10100", "type": "concept", "title": "Rule-based variation"}, {"id": "0b811047-5858-4c87-a6ed-e54b89e2a38b", "type": "concept", "title": "Theme and formal coherence"}], "description": "A series helps students deepen a question across multiple works."}, {"id": "7588fbf4-b483-45be-8332-c2683a08e2bd", "type": "subtopic", "title": "Emerging personal voice", "children": [{"id": "461f0116-e95e-4cde-8d57-5a4dc9412b18", "type": "concept", "title": "Influence maps"}, {"id": "343777b5-bea0-4226-9c7c-1d2fb663a287", "type": "concept", "title": "Material preferences"}, {"id": "aa59fb6b-c17f-4df8-8c86-2b024f46d1e2", "type": "concept", "title": "Artist statements in progress"}], "description": "Voice is built from choices, interests, constraints, and recurring visual problems."}]}, {"id": "876fb74a-e31f-46c7-97e5-b2fa22e13436", "type": "topic", "title": "Documentation, Presentation, Framing, and Portfolio", "description": "Students need to present and document paintings clearly so the work can be reviewed, archived, submitted, and discussed. Professional presentation is treated as part of studio craft.", "children": [{"id": "de25efd0-fa41-4fb7-ab44-73213503fc17", "type": "subtopic", "title": "Photographing paintings", "children": [{"id": "148eb320-80f8-44c9-9333-58693b434dac", "type": "concept", "title": "Lighting setup"}, {"id": "8182a599-b7b6-4c3d-a61c-c57326784586", "type": "concept", "title": "Color correction basics"}, {"id": "0633fe48-0faa-4933-85c0-745da8b7c67c", "type": "concept", "title": "Cropping and file naming"}], "description": "Good documentation preserves color, scale, surface, and edge quality."}, {"id": "0d024c3f-e67b-4f7e-a812-0cfcf527c7da", "type": "subtopic", "title": "Presentation and installation", "children": [{"id": "63f94f93-3d66-43c5-a444-ffd2017f6c1d", "type": "concept", "title": "Edges and hanging hardware"}, {"id": "f6967a35-f711-4e47-a863-084ddfe2e0d3", "type": "concept", "title": "Framing and alternatives"}, {"id": "88b21878-f1c9-4a75-a2f6-ef120bfc0c15", "type": "concept", "title": "Wall spacing and sightlines"}], "description": "Presentation choices affect how the painting meets the viewer."}, {"id": "2b353e0f-8ee9-4cf5-9744-35ea592c005e", "type": "subtopic", "title": "Portfolio assembly", "children": [{"id": "168845a0-53f3-49cc-b010-b12e29d4c9ba", "type": "concept", "title": "Image order"}, {"id": "4f9f9618-8117-42dc-b63c-d14ade03a815", "type": "concept", "title": "Captions and metadata"}, {"id": "649e0edb-79ba-455d-81ac-54b819ea7aae", "type": "concept", "title": "Short project descriptions"}], "description": "A beginning portfolio teaches students how to select, sequence, and explain work."}]}, {"id": "29c00c3b-e27f-4f97-8456-48e2da1543a6", "type": "topic", "title": "Professional Practice, Ethics, Materials Sustainability, and Studio Habits", "description": "Even introductory students benefit from professional habits: ethical image use, sustainable material choices, accurate documentation, and respectful studio culture. These practices support long-term creative work.", "children": [{"id": "28eb45b8-dc75-46c3-89cb-76677afc2d7a", "type": "subtopic", "title": "Ethical image and source use", "children": [{"id": "a23a03f9-6853-42ec-88bf-6e8d3afad3ef", "type": "concept", "title": "Copyright basics"}, {"id": "0c73fca4-3f3b-4dbf-842b-970726b2c624", "type": "concept", "title": "Cultural appropriation concerns"}, {"id": "8ff7e5db-88c8-4f48-aa04-f353dcad5f00", "type": "concept", "title": "Reference logs and citations"}], "description": "Painters must understand when source material becomes research, influence, quotation, or misuse."}, {"id": "57b11305-2ee9-4d8d-abe5-9e97965c3ced", "type": "subtopic", "title": "Sustainable material decisions", "children": [{"id": "45856483-80a2-49a9-aad0-3902e24797e3", "type": "concept", "title": "Low-toxicity alternatives"}, {"id": "02f8d547-797c-4d6a-8b10-987e22340187", "type": "concept", "title": "Waste reduction"}, {"id": "a543d3b3-2533-4ec0-b25d-f1719e768d14", "type": "concept", "title": "Reusing supports and responsible disposal"}], "description": "Material choices carry environmental and health consequences."}, {"id": "624a53b7-8087-4935-9a62-1509c9baee4e", "type": "subtopic", "title": "Studio professionalism", "children": [{"id": "6e04f76d-c9b8-44c8-a4d4-ded0295ad714", "type": "concept", "title": "Time management"}, {"id": "3a75b008-2566-4117-914c-2bc036b4f1d7", "type": "concept", "title": "Shared-space etiquette"}, {"id": "5a7c7274-2672-497b-972d-ec3603f41484", "type": "concept", "title": "Storage, labeling, and maintenance"}], "description": "Reliable studio habits help students sustain ambitious projects."}]}, {"id": "0ff572ce-300f-4b26-b7e0-11b2306e9101", "type": "topic", "title": "Final Painting Project and Reflective Artist Statement", "description": "The final project asks students to synthesize observation, material technique, composition, color, critique, and personal direction. It should demonstrate both craft growth and conceptual awareness.", "children": [{"id": "bd501d8c-c96c-4b48-872e-7f6c6b25b90a", "type": "subtopic", "title": "Project proposal and planning", "children": [{"id": "ca70e1f4-c6dc-4014-96d0-4e163b9ed5fb", "type": "concept", "title": "Concept statement"}, {"id": "2fc4dc01-eb31-458b-9af9-dbb65fc7f2f8", "type": "concept", "title": "Reference images and artist precedents"}, {"id": "745044af-cfd6-4bf8-ab1a-4210074068d0", "type": "concept", "title": "Materials and timeline"}], "description": "A proposal helps students define aims, constraints, references, and criteria before execution."}, {"id": "5f2175a3-12c8-4311-b8d4-81ee4b1d5cb1", "type": "subtopic", "title": "Execution and revision", "children": [{"id": "490aca44-49a7-48e5-a650-09ba88260a04", "type": "concept", "title": "Midpoint critique"}, {"id": "39c39382-ce4e-4c0a-a398-906d8ccdc27a", "type": "concept", "title": "Revision schedule"}, {"id": "a430d102-578d-4db4-aaf7-4e3f40554213", "type": "concept", "title": "Technical troubleshooting"}], "description": "The final painting develops through checkpoints, critique, and technical problem-solving."}, {"id": "42c7d765-bc3c-4fcb-ba02-3d9e155ec329", "type": "subtopic", "title": "Reflective artist statement", "children": [{"id": "607005c8-4bfa-4955-bec9-bc6da857edd8", "type": "concept", "title": "Formal and material decisions"}, {"id": "c0fc64d3-e744-447c-ba00-dfef1a9dc495", "type": "concept", "title": "Conceptual intent"}, {"id": "536ccd07-0c27-48da-a1b8-97d188cafe1f", "type": "concept", "title": "Learning assessment and future direction"}], "description": "Reflection teaches students to connect decisions, outcomes, and next steps in clear language."}]}], "dbBacked": true}$pa1json$::jsonb,
